/* Minimal parallel AES-GCM using OpenSSL EVP, one context per thread.
   Each thread encrypts a disjoint chunk of plaintext with CTR (via GCM without
   AAD/tag) ... actually GCM encrypt of a chunk is not independent because of
   the GHASH chaining and counter. For pure speed of *correct* GCM we cannot
   just split encrypt calls. This file instead times a single EVP encrypt to
   confirm OpenSSL speed from C, and a parallel CTR-only (AES-CTR) speed. */
#include <openssl/evp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t n = 60000L * 1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n + 32);
    unsigned char key[16], nonce[12];
    memset(pt, 1, n);
    memset(key, 2, 16);
    memset(nonce, 3, 12);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen = 0, total = 0;
    double t0 = now();
    int reps = 3;
    for (int r = 0; r < reps; r++) {
        EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, ct, &outlen, pt, (int)n);
        total = outlen;
        EVP_EncryptFinal_ex(ctx, ct + total, &outlen);
        total += outlen;
        unsigned char tag[16];
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    double t1 = now();
    printf("C EVP AES-GCM: %.4f sec/op  (%.1f MB/s) total=%d\n", (t1-t0)/reps, (n/1e6)/((t1-t0)/reps), total);
    EVP_CIPHER_CTX_free(ctx);
    free(pt); free(ct);
    return 0;
}
