{"command":"cd "$HOME/aesbench" && cat > aesgcm_fast.c << 'EOF'
#include <openssl/evp.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

/*
 * aesgcm_encrypt:
 *   key, key_len (16/24/32)
 *   nonce, nonce_len
 *   pt, pt_len
 *   aad, aad_len (aad may be NULL if aad_len==0)
 *   ct_out  (must have pt_len bytes)
 *   tag_out (must have 16 bytes)
 * returns 0 on success, -1 on failure
 *
 * Uses a thread-local reused EVP context and 16KB update chunks, which
 * benchmarks substantially faster than one giant EncryptUpdate on this CPU.
 */
static __thread EVP_CIPHER_CTX *tls_ctx = NULL;
static __thread int tls_key_len = 0;

static const EVP_CIPHER *cipher_for(int key_len) {
    if (key_len == 16) return EVP_aes_128_gcm();
    if (key_len == 24) return EVP_aes_192_gcm();
    if (key_len == 32) return EVP_aes_256_gcm();
    return NULL;
}

int aesgcm_encrypt(
    const unsigned char *key, int key_len,
    const unsigned char *nonce, int nonce_len,
    const unsigned char *pt, int pt_len,
    const unsigned char *aad, int aad_len,
    unsigned char *ct_out,
    unsigned char *tag_out
) {
    const EVP_CIPHER *cipher = cipher_for(key_len);
    if (!cipher) return -1;
    if (!tls_ctx || tls_key_len != key_len) {
        if (tls_ctx) EVP_CIPHER_CTX_free(tls_ctx);
        tls_ctx = EVP_CIPHER_CTX_new();
        if (!tls_ctx) return -1;
        if (EVP_EncryptInit_ex(tls_ctx, cipher, NULL, NULL, NULL) != 1) return -1;
        tls_key_len = key_len;
    }
    if (EVP_CIPHER_CTX_ctrl(tls_ctx, EVP_CTRL_GCM_SET_IVLEN, nonce_len, NULL) != 1) return -1;
    if (EVP_EncryptInit_ex(tls_ctx, NULL, NULL, key, nonce) != 1) return -1;

    int outlen = 0;
    if (aad && aad_len > 0) {
        if (EVP_EncryptUpdate(tls_ctx, NULL, &outlen, aad, aad_len) != 1) return -1;
    }
    /* 16KB chunks: empirically much faster than one huge update (cache/AES-NI path) */
    const int CHUNK = 16384;
    int off = 0;
    while (off < pt_len) {
        int c = pt_len - off;
        if (c > CHUNK) c = CHUNK;
        if (EVP_EncryptUpdate(tls_ctx, ct_out + off, &outlen, pt + off, c) != 1) return -1;
        off += c;
    }
    if (EVP_EncryptFinal_ex(tls_ctx, ct_out + off, &outlen) != 1) return -1;
    if (EVP_CIPHER_CTX_ctrl(tls_ctx, EVP_CTRL_GCM_GET_TAG, 16, tag_out) != 1) return -1;
    return 0;
}
EOF
