import ctypes, os, time
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

lib = ctypes.CDLL(os.path.expanduser("~/aesbench/libaesgcm_fast.dylib"))
lib.aesgcm_encrypt.argtypes = [
    ctypes.c_void_p, ctypes.c_int,
    ctypes.c_void_p, ctypes.c_int,
    ctypes.c_void_p, ctypes.c_int,
    ctypes.c_void_p, ctypes.c_int,
    ctypes.c_void_p,
    ctypes.c_void_p,
]
lib.aesgcm_encrypt.restype = ctypes.c_int
ctypes.pythonapi.PyBytes_AsString.argtypes = [ctypes.py_object]
ctypes.pythonapi.PyBytes_AsString.restype = ctypes.c_void_p
ctypes.pythonapi.PyByteArray_AsString.argtypes = [ctypes.py_object]
ctypes.pythonapi.PyByteArray_AsString.restype = ctypes.c_void_p

def ptr(b):
    if b is None:
        return None
    if isinstance(b, bytearray):
        return ctypes.pythonapi.PyByteArray_AsString(b)
    return ctypes.pythonapi.PyBytes_AsString(b)

def enc(key, nonce, pt, aad):
    ct = bytearray(len(pt))
    tag = bytearray(16)
    aad_len = 0 if not aad else len(aad)
    rc = lib.aesgcm_encrypt(ptr(key), len(key), ptr(nonce), len(nonce), ptr(pt), len(pt), ptr(aad) if aad_len else None, aad_len, ptr(ct), ptr(tag))
    if rc != 0:
        raise RuntimeError("enc failed")
    return bytes(ct), bytes(tag)

key = os.urandom(16)
nonce = os.urandom(12)
pt_small = os.urandom(1000)
aad = os.urandom(32)
aes = AESGCM(key)
for a in (aad, b"", None):
    ref = aes.encrypt(nonce, pt_small, a)
    ct, tag = enc(key, nonce, pt_small, a)
    print("small match", a is None or len(a), ref == ct+tag)

N = 60000*1024
pt = os.urandom(N)
ref = aes.encrypt(nonce, pt, aad)
ct, tag = enc(key, nonce, pt, aad)
print("full match", ref == ct+tag)

# speed
enc(key, nonce, pt, aad)
t0 = time.perf_counter()
reps = 3
for _ in range(reps):
    enc(key, nonce, pt, aad)
t1 = time.perf_counter()
print(f"C lib: {(t1-t0)/reps:.4f} sec  {(N/1e6)/((t1-t0)/reps):.0f} MB/s")
t0 = time.perf_counter()
for _ in range(reps):
    aes.encrypt(nonce, pt, aad)
t1 = time.perf_counter()
print(f"cryptography: {(t1-t0)/reps:.4f} sec  speedup {((t1-t0)/reps)/((N and 1)):.4f}")
print("speedup", ((t1-t0)) / ((t1-t0) and 1))
EOF"}

