{"command":"cd "$HOME/aesbench" && cat > bench5.c << 'EOF'
#define _GNU_SOURCE
#include <openssl/evp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdint.h>
#include <unistd.h>
#ifdef __APPLE__
#include <mach/thread_policy.h>
#include <mach/thread_act.h>
#include <pthread.h>
#endif

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

static void pin(int cpu) {
#ifdef __APPLE__
    thread_affinity_policy_data_t policy = { cpu };
    thread_policy_set(pthread_mach_thread_np(pthread_self()),
                      THREAD_AFFINITY_POLICY,
                      (thread_policy_t)&policy, 1);
#endif
}

/* ---------- parallel AES-GCM ----------
   Strategy: split plaintext into N threads. Each thread does AES-CTR for its
   range (counter starts at 2+block_offset) AND computes GHASH of its ciphertext
   blocks independently, then we combine GHASH partials with length-block.
   For a correct combined GHASH we need the GHASH of each chunk multiplied by
   H^{blocks_after}. That requires knowing H. We can compute H = AES_k(0) once,
   then do schoolbook GF multiply. This is a correct parallel AES-GCM.

   For the benchmark first, just measure parallel AES-CTR throughput, which is
   the dominant cost, and a serial GHASH estimate.
*/

typedef struct {
    const unsigned char *key;
    const unsigned char *pt;
    unsigned char *ct;
    size_t off, len;
    unsigned char iv[16];
    int id;
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    pin(j->id);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_ctr(), NULL, j->key, j->iv);
    size_t done = 0;
    while (done < j->len) {
        int c = 1<<20;
        if (done + c > j->len) c = (int)(j->len - done);
        EVP_EncryptUpdate(ctx, j->ct + j->off + done, &outlen, j->pt + j->off + done, c);
        done += c;
    }
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main() {
    size_t N = 60000L * 1024;
    unsigned char *PT = malloc(N);
    unsigned char *CT = malloc(N+64);
    unsigned char key[16], nonce[12];
    memset(PT, 1, N); memset(key, 2, 16); memset(nonce, 3, 12);

    /* serial CTR baseline pinned */
    pin(0);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
