    __m128i xmm0 = X0;
    __m128i xmm1 = X1;
    /* shift-xor reduction, 4 steps of the low 128 into the high, poly = 0xe1<<120 reflected = 0x87 at the top of a left shift. */
    __m128i psll = _mm_slli_epi64(xmm0, 57);          /* prepare x^7,x^2,x^1 contributions via later shuffle? */
    /* Use the compact method from https://github.com/intel/intel-ipsec-mb ghash.
