/* ---------- AES key schedule + CTR via AES-NI ---------- */

typedef struct {
    __m128i rk[15];
    int nrounds; /* 10, 12, 14 */
} aes_key_t;

static inline __m128i aes_key_expand(__m128i key, __m128i assist) {
    key = _mm_xor_si128(key, _mm_slli_si128(key, 4));
    key = _mm_xor_si128(key, _mm_slli_si128(key, 4));
    key = _mm_xor_si128(key, _mm_slli_si128(key, 4));
    return _mm_xor_si128(key, assist);
}

static void aes128_expand(aes_key_t *ks, const uint8_t key[16]) {
    ks->nrounds = 10;
    __m128i k = _mm_loadu_si128((const __m128i *)key);
    ks->rk[0] = k;
    #define EXPAND(i, rcon) do { \
        __m128i a = _mm_aeskeygenassist_si128(k, rcon); \
        k = aes_key_expand(k, _mm_shuffle_epi32(a, 0xff)); \
        ks->rk[i] = k; \
    } while (0)
    EXPAND(1, 0x01); EXPAND(2, 0x02); EXPAND(3, 0x04); EXPAND(4, 0x08);
    EXPAND(5, 0x10); EXPAND(6, 0x20); EXPAND(7, 0x40); EXPAND(8, 0x80);
    EXPAND(9, 0x1b); EXPAND(10, 0x36);
    #undef EXPAND
}

/* AES-256 expand */
static void aes256_expand(aes_key_t *ks, const uint8_t key[32]) {
    ks->nrounds = 14;
    __m128i k0 = _mm_loadu_si128((const __m128i *)key);
    __m128i k1 = _mm_loadu_si128((const __m128i *)(key + 16));
    ks->rk[0] = k0; ks->rk[1] = k1;
    int idx = 2;
    __m128i rcon = _mm_set_epi32(0, 0, 0, 1);
    for (int round = 0; round < 7; round++) {
        __m128i a = _mm_aeskeygenassist_si128(k1, (int)_mm_cvtsi128_si32(rcon) ? 0 : 0);
        (void)a;
        /* do it with explicit rcon values */
        break;
    }
    const int rcons[7] = {0x01,0x02,0x04,0x08,0x10,0x20,0x40};
    for (int i = 0; i < 7; i++) {
        __m128i assist = _mm_aeskeygenassist_si128(k1, rcons[i]);
        assist = _mm_shuffle_epi32(assist, 0xff);
        k0 = aes_key_expand(k0, assist);
        ks->rk[idx++] = k0;
        assist = _mm_aeskeygenassist_si128(k0, 0);
        assist = _mm_shuffle_epi32(assist, 0xaa);
        k1 = aes_key_expand(k1, assist);
        if (idx < 15) ks->rk[idx++] = k1;
    }
    (void)rcon;
}

/* AES-192 is less common here (benchmark uses 128). Implement via OpenSSL for non-128
   to keep this file focused; the parallel path below handles 128 natively and falls
   back for others. */

static inline __m128i aes_encrypt_block(const aes_key_t *ks, __m128i b) {
    b = _mm_xor_si128(b, ks->rk[0]);
    for (int r = 1; r < ks->nrounds; r++) b = _mm_aesenc_si128(b, ks->rk[r]);
    return _mm_aesenclast_si128(b, ks->rk[ks->nrounds]);
}

/* 8-way CTR. counter is the 32-bit big-endian GCM counter (last 4 bytes of the
   16-byte counter block whose first 12 bytes are the nonce). */
static void aes_ctr_xor_128(const aes_key_t *ks, const uint8_t nonce[12],
                            uint32_t counter, const uint8_t *in, uint8_t *out, size_t len) {
    /* Build initial counter block */
    uint8_t cb[16];
    memcpy(cb, nonce, 12);
    size_t blocks = len / 16;
    size_t i = 0;
    while (i + 8 <= blocks) {
        __m128i c[8];
        for (int k = 0; k < 8; k++) {
            uint32_t ctr = counter + (uint32_t)(i + k);
            cb[12] = (ctr >> 24) & 0xff; cb[13] = (ctr >> 16) & 0xff;
            cb[14] = (ctr >> 8) & 0xff; cb[15] = ctr & 0xff;
            c[k] = _mm_loadu_si128((const __m128i *)cb);
            c[k] = _mm_xor_si128(c[k], ks->rk[0]);
        }
        for (int r = 1; r < ks->nrounds; r++) {
            for (int k = 0; k < 8; k++) c[k] = _mm_aesenc_si128(c[k], ks->rk[r]);
        }
        for (int k = 0; k < 8; k++) {
            c[k] = _mm_aesenclast_si128(c[k], ks->rk[ks->nrounds]);
            __m128i p = _mm_loadu_si128((const __m128i *)(in + (i + k) * 16));
            _mm_storeu_si128((__m128i *)(out + (i + k) * 16), _mm_xor_si128(c[k], p));
        }
        i += 8;
    }
    while (i < blocks) {
        uint32_t ctr = counter + (uint32_t)i;
        cb[12] = (ctr >> 24) & 0xff; cb[13] = (ctr >> 16) & 0xff;
        cb[14] = (ctr >> 8) & 0xff; cb[15] = ctr & 0xff;
        __m128i c = aes_encrypt_block(ks, _mm_loadu_si128((const __m128i *)cb));
        __m128i p = _mm_loadu_si128((const __m128i *)(in + i * 16));
        _mm_storeu_si128((__m128i *)(out + i * 16), _mm_xor_si128(c, p));
        i++;
    }
    size_t rem = len - blocks * 16;
    if (rem) {
        uint32_t ctr = counter + (uint32_t)blocks;
        cb[12] = (ctr >> 24) & 0xff; cb[13] = (ctr >> 16) & 0xff;
        cb[14] = (ctr >> 8) & 0xff; cb[15] = ctr & 0xff;
        __m128i c = aes_encrypt_block(ks, _mm_loadu_si128((const __m128i *)cb));
        uint8_t ks_stream[16];
        _mm_storeu_si128((__m128i *)ks_stream, c);
        for (size_t j = 0; j < rem; j++) out[blocks * 16 + j] = in[blocks * 16 + j] ^ ks_stream[j];
    }
}

/* ---------- parallel driver ---------- */

typedef struct {
    const aes_key_t *ks;
    const uint8_t *nonce;
    const uint8_t *pt;
    uint8_t *ct;
    size_t off;       /* byte offset, multiple of 16 (except possibly last) */
    size_t len;
    __m128i H;        /* reflected H */
    __m128i ghash;    /* output: GHASH of this chunk's ciphertext (reflected) */
    uint64_t blocks;  /* full blocks hashed in this chunk (partial tail excluded; handled by main) */
    int id;
} worker_arg_t;

static void ghash_blocks(__m128i H, const uint8_t *data, size_t len, __m128i *acc) {
    /* hash full blocks only; caller handles tail */
    size_t blocks = len / 16;
    __m128i a = *acc;
    size_t i = 0;
    /* 4-way delayed reduction would be faster; start with 1-way correct */
    const __m128i *p = (const __m128i *)data;
    for (; i < blocks; i++) {
        __m128i x = byteswap16(_mm_loadu_si128(p + i));
        a = gfmul_reflected(_mm_xor_si128(a, x), H);
    }
    *acc = a;
}

static void *worker_fn(void *arg) {
    worker_arg_t *w = arg;
    uint32_t counter = 2u + (uint32_t)(w->off / 16);
    aes_ctr_xor_128(w->ks, w->nonce, counter, w->pt + w->off, w->ct + w->off, w->len);
    __m128i acc = _mm_setzero_si128();
    size_t full = w->len & ~15UL;
    ghash_blocks(w->H, w->ct + w->off, full, &acc);
    w->ghash = acc;
    w->blocks = full / 16;
    return NULL;
}

/* H^n via square-and-multiply, reflected. n can be large (up to ~2^32). */
static __m128i h_pow(__m128i H, uint64_t n) {
    __m128i result = byteswap16(_mm_set_epi64x(0, 1) /* wrong */);
    /* identity in reflected GHASH is the byte-swapped 0x00..01? 
       Mathematical identity is 1 (bit 0 set) which in memory order is last bit of last byte,
       i.e. byte 15 = 0x01? No: GCM treats the block as a 128-bit big-endian integer, so
       the multiplicative identity is the integer 1, whose big-endian representation is
       00 00 ... 00 01. In reflected register order (byteswap), that is 01 00 ... 00,
       i.e. low byte = 0x01. byteswap16 of memory {0,0,...,1} = {1,0,0,...,0}. */
    uint8_t one_mem[16] = {0}; one_mem[15] = 1;
    result = byteswap16(_mm_loadu_si128((const __m128i *)one_mem));
    __m128i base = H;
    while (n) {
        if (n & 1) result = gfmul_reflected(result, base);
        base = gfmul_reflected(base, base);
        n >>= 1;
    }
    return result;
}

int aesgcm_encrypt_128(
    const uint8_t *key,
    const uint8_t *nonce, int nonce_len,
    const uint8_t *pt, int pt_len,
    const uint8_t *aad, int aad_len,
    uint8_t *ct_out,
    uint8_t *tag_out,
    int nthreads
) {
    if (nonce_len != 12) return -1; /* only 96-bit nonce in the fast path */
    if (nthreads < 1) nthreads = 1;
    if (nthreads > MAX_THREADS) nthreads = MAX_THREADS;

    aes_key_t ks;
    aes128_expand(&ks, key);

    /* H = AES_k(0) */
    __m128i h_block = aes_encrypt_block(&ks, _mm_setzero_si128());
    __m128i H = byteswap16(h_block);

    if (pt_len < 0) return -1;
    size_t N = (size_t)pt_len;

    if (nthreads > 1 && N >= 1024 * 1024) {
        /* split into nthreads ranges, each a multiple of 16 except the last */
        size_t full = N & ~15UL;
        size_t chunk = (full / nthreads) & ~15UL;
        if (chunk == 0) nthreads = 1;
        else {
            pthread_t th[MAX_THREADS];
            worker_arg_t args[MAX_THREADS];
            int live = 0;
            for (int i = 0; i < nthreads; i++) {
                size_t off = (size_t)i * chunk;
                if (off >= full) break;
                size_t len = (i == nthreads - 1) ? (N - off) : chunk;
                args[i].ks = &ks;
                args[i].nonce = nonce;
                args[i].pt = pt;
                args[i].ct = ct_out;
                args[i].off = off;
                args[i].len = len;
                args[i].H = H;
                args[i].id = i;
                pthread_create(&th[i], NULL, worker_fn, &args[i]);
                live++;
            }
            for (int i = 0; i < live; i++) pthread_join(th[i], NULL);

            /* AAD GHASH (small) */
            __m128i acc = _mm_setzero_si128();
            if (aad && aad_len > 0) {
                size_t aad_full = (size_t)aad_len & ~15UL;
                ghash_blocks(H, aad, aad_full, &acc);
                size_t aad_rem = (size_t)aad_len - aad_full;
                if (aad_rem) {
                    uint8_t last[16] = {0};
                    memcpy(last, aad + aad_full, aad_rem);
                    ghash_blocks(H, last, 16, &acc);
                }
            }
            /* combine chunk ghashes: acc = (...((acc * H^{b0} XOR g0) * H^{b1} XOR g1)...) */
            for (int i = 0; i < live; i++) {
                if (args[i].blocks) {
                    __m128i Hp = h_pow(H, args[i].blocks);
                    acc = _mm_xor_si128(gfmul_reflected(acc, Hp), args[i].ghash);
                }
                /* partial last block lives only in the last chunk */
            }
            size_t rem = N & 15UL;
            if (rem) {
                uint8_t last[16] = {0};
                memcpy(last, ct_out + (N - rem), rem);
                ghash_blocks(H, last, 16, &acc);
            }
            /* length block */
            uint8_t lenb[16];
            uint64_t aad_bits = (uint64_t)aad_len * 8;
            uint64_t pt_bits = (uint64_t)pt_len * 8;
            for (int i = 7; i >= 0; i--) { lenb[i] = aad_bits & 0xff; aad_bits >>= 8; }
            for (int i = 15; i >= 8; i--) { lenb[i] = pt_bits & 0xff; pt_bits >>= 8; }
            ghash_blocks(H, lenb, 16, &acc);

            /* tag = AES_k(counter 1) XOR byteswap(acc) */
            uint8_t cb[16];
            memcpy(cb, nonce, 12);
            cb[12] = 0; cb[13] = 0; cb[14] = 0; cb[15] = 1;
            __m128i s = aes_encrypt_block(&ks, _mm_loadu_si128((const __m128i *)cb));
            __m128i tag = _mm_xor_si128(s, byteswap16(acc));
            _mm_storeu_si128((__m128i *)tag_out, tag);
            return 0;
        }
    }

    /* serial path */
    aes_ctr_xor_128(&ks, nonce, 2, pt, ct_out, N);
    __m128i acc = _mm_setzero_si128();
    if (aad && aad_len > 0) {
        size_t aad_full = (size_t)aad_len & ~15UL;
        ghash_blocks(H, aad, aad_full, &acc);
        size_t aad_rem = (size_t)aad_len - aad_full;
        if (aad_rem) {
            uint8_t last[16] = {0};
            memcpy(last, aad + aad_full, aad_rem);
            ghash_blocks(H, last, 16, &acc);
        }
    }
    size_t full = N & ~15UL;
    ghash_blocks(H, ct_out, full, &acc);
    size_t rem = N & 15UL;
    if (rem) {
        uint8_t last[16] = {0};
        memcpy(last, ct_out + full, rem);
        ghash_blocks(H, last, 16, &acc);
    }
    uint8_t lenb[16];
    uint64_t aad_bits = (uint64_t)(aad_len < 0 ? 0 : aad_len) * 8;
    uint64_t pt_bits = (uint64_t)pt_len * 8;
    for (int i = 7; i >= 0; i--) { lenb[i] = (uint8_t)(aad_bits & 0xff); aad_bits >>= 8; }
    for (int i = 15; i >= 8; i--) { lenb[i] = (uint8_t)(pt_bits & 0xff); pt_bits >>= 8; }
    ghash_blocks(H, lenb, 16, &acc);
    uint8_t cb[16];
    memcpy(cb, nonce, 12);
    cb[12] = 0; cb[13] = 0; cb[14] = 0; cb[15] = 1;
    __m128i s = aes_encrypt_block(&ks, _mm_loadu_si128((const __m128i *)cb));
    __m128i tag = _mm_xor_si128(s, byteswap16(acc));
    _mm_storeu_si128((__m128i *)tag_out, tag);
    return 0;
}

#ifdef TEST_MAIN
#include <time.h>
static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return ts.tv_sec + ts.tv_nsec*1e-9; }
