    self_test_gfmul();
    size_t N = 60000L * 1024;
    uint8_t *pt = malloc(N), *ct = malloc(N);
    uint8_t key[16], nonce[12], tag[16], aad[32];
    memset(pt, 0x11, N);
    for (int i = 0; i < 16; i++) key[i] = i+1;
    for (int i = 0; i < 12; i++) nonce[i] = i;
    for (int i = 0; i < 32; i++) aad[i] = i*3;

    /* small correctness printed for external compare */
    uint8_t ct_small[64], tag_small[16];
    uint8_t pt_small[50];
    for (int i = 0; i < 50; i++) pt_small[i] = i;
    aesgcm_encrypt_128(key, nonce, 12, pt_small, 50, aad, 32, ct_small, tag_small, 1);
    printf("serial small ct: ");
