        double t1 = now();
        printf("threads %d: %.4f s  %.0f MB/s\n", nt, (t1-t0)/reps, (N/1e6)/((t1-t0)/reps));
    }
    /* empty aad / no aad */
    aesgcm_encrypt_128(key, nonce, 12, pt_small, 50, NULL, 0, ct_small, tag_small, 1);
    printf("empty aad tag ");
    for (int i = 0; i < 16; i++) printf("%02x", tag_small[i]);
    printf("\n");
    return 0;
}
