#include <wmmintrin.h>
#include <emmintrin.h>
#include <tmmintrin.h>
#include <smmintrin.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>

static void ghash_mul_ref(uint8_t out[16], const uint8_t x[16], const uint8_t h[16]) {
    uint8_t z[16] = {0};
    uint8_t v[16];
    memcpy(v, h, 16);
    for (int i = 0; i < 16; i++) {
        uint8_t xb = x[i];
        for (int bit = 7; bit >= 0; bit--) {
            if ((xb >> bit) & 1) for (int k = 0; k < 16; k++) z[k] ^= v[k];
            int lsb = v[15] & 1;
            for (int k = 15; k > 0; k--) v[k] = (uint8_t)((v[k] >> 1) | (v[k-1] << 7));
            v[0] = (uint8_t)(v[0] >> 1);
            if (lsb) v[0] ^= 0xe1;
        }
    }
    memcpy(out, z, 16);
