/* schoolbook product of two reflected (byte-swapped) 128-bit values -> 256-bit lo/hi
   in clmul bit order (bit 0 = low bit of low 64). */
static void product(__m128i a, __m128i b, __m128i *lo, __m128i *hi) {
    __m128i z0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i z1 = _mm_clmulepi64_si128(a, b, 0x10);
    __m128i z2 = _mm_clmulepi64_si128(a, b, 0x01);
    __m128i z3 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i zmid = _mm_xor_si128(z1, z2);
    *lo = _mm_xor_si128(z0, _mm_slli_si128(zmid, 8));
    *hi = _mm_xor_si128(z3, _mm_srli_si128(zmid, 8));
}

int main() {
    uint8_t x[16], h[16], ref[16];
    for (int i = 0; i < 16; i++) { x[i] = (uint8_t)(i*17+3); h[i] = (uint8_t)(i*9+1); }
    ghash_mul_ref(ref, x, h);
    p("ref", ref);

    __m128i a = bswap16(_mm_loadu_si128((const __m128i*)x));
    __m128i b = bswap16(_mm_loadu_si128((const __m128i*)h));
    __m128i lo, hi;
    product(a, b, &lo, &hi);
    uint8_t lob[16], hib[16];
    _mm_storeu_si128((__m128i*)lob, lo);
    _mm_storeu_si128((__m128i*)hib, hi);
    p("lo", lob); p("hi", hib);

    /* Also product of NON-swapped, and of bit-reflected within bytes only (pshufb reverse bits? skip). */

    /* Try reduction polynomial constants other than 0x87: 0xe1, and also reducing the HIGH half instead. */
    uint64_t consts[] = {0x87, 0xe1, 0x1b, 0xc2, 0x43};
    for (int ci = 0; ci < 5; ci++) {
        __m128i L = lo, Hh = hi;
