        __m128i r0 = _mm_clmulepi64_si128(_mm_move_epi64(L), p87, 0x00);
        L = _mm_xor_si128(L, _mm_slli_si128(r0, 8));
        Hh = _mm_xor_si128(Hh, _mm_srli_si128(r0, 8));
        __m128i r1 = _mm_clmulepi64_si128(_mm_srli_si128(L, 8), p87, 0x00);
        Hh = _mm_xor_si128(Hh, r1);
        uint8_t o[16];
        _mm_storeu_si128((__m128i*)o, bswap16(Hh));
        char name[32]; snprintf(name, sizeof name, "red %llx", (unsigned long long)consts[ci]);
        p(name, o);
        printf("   match %d\n", memcmp(o, ref, 16)==0);
    }

    /* Maybe the product bit order is reversed: swap lo and hi roles, reduce hi into lo. */
    for (int ci = 0; ci < 3; ci++) {
