        __m128i p87 = _mm_set_epi64x(0, c);
        __m128i r0 = _mm_clmulepi64_si128(_mm_move_epi64(L), p87, 0x00);
        L = _mm_xor_si128(L, _mm_slli_si128(r0, 8));
        Hh = _mm_xor_si128(Hh, _mm_srli_si128(r0, 8));
        __m128i r1 = _mm_clmulepi64_si128(_mm_srli_si128(L, 8), p87, 0x00);
        Hh = _mm_xor_si128(Hh, r1);
