/* bit-reverse a 64-bit word */
static inline uint64_t brev64(uint64_t x) {
    x = ((x & 0x5555555555555555ULL) << 1) | ((x >> 1) & 0x5555555555555555ULL);
    x = ((x & 0x3333333333333333ULL) << 2) | ((x >> 2) & 0x3333333333333333ULL);
    x = ((x & 0x0f0f0f0f0f0f0f0fULL) << 4) | ((x >> 4) & 0x0f0f0f0f0f0f0f0fULL);
    x = ((x & 0x00ff00ff00ff00ffULL) << 8) | ((x >> 8) & 0x00ff00ff00ff00ffULL);
    x = ((x & 0x0000ffff0000ffffULL) << 16) | ((x >> 16) & 0x0000ffff0000ffffULL);
    return (x << 32) | (x >> 32);
}
static inline __m128i bitreverse128(__m128i v) {
    uint64_t lo = (uint64_t)_mm_cvtsi128_si64(v);
    uint64_t hi = (uint64_t)_mm_extract_epi64(v, 1);
    /* after full 128-bit reverse, old hi becomes new lo (bit-reversed) and vice versa */
    return _mm_set_epi64x((long long)brev64(lo), (long long)brev64(hi));
}

static void p(const char *n, const uint8_t *b){ printf("%-16s ", n); for(int i=0;i<16;i++) printf("%02x", b[i]); printf("\n"); }

static void mul_via_bitreverse(uint8_t out[16], const uint8_t x[16], const uint8_t h[16]) {
    /* Load as little-endian 128 (native), bitreverse so bit 127 of the big-endian
       integer is bit 0, clmul, reduce with poly x^128+x^7+x^2+x+1 = low bits 0x87,
       bitreverse back. */
    __m128i a = bitreverse128(_mm_loadu_si128((const __m128i*)x));
    __m128i b = bitreverse128(_mm_loadu_si128((const __m128i*)h));
    __m128i z0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i z1 = _mm_clmulepi64_si128(a, b, 0x10);
    __m128i z2 = _mm_clmulepi64_si128(a, b, 0x01);
    __m128i z3 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i mid = _mm_xor_si128(z1, z2);
    __m128i lo = _mm_xor_si128(z0, _mm_slli_si128(mid, 8));
    __m128i hi = _mm_xor_si128(z3, _mm_srli_si128(mid, 8));
    /* reduce: for bits 0..127, if set, xor 0x87 shifted to bit+128 */
    __m128i p87 = _mm_set_epi64x(0, 0x87);
    __m128i r0 = _mm_clmulepi64_si128(_mm_move_epi64(lo), p87, 0x00);
    lo = _mm_xor_si128(lo, _mm_slli_si128(r0, 8));
    hi = _mm_xor_si128(hi, _mm_srli_si128(r0, 8));
    __m128i r1 = _mm_clmulepi64_si128(_mm_srli_si128(lo, 8), p87, 0x00);
    hi = _mm_xor_si128(hi, r1);
    __m128i res = bitreverse128(hi);
    _mm_storeu_si128((__m128i*)out, res);
}

int main() {
    uint8_t x[16], h[16], ref[16], o[16];
    for (int i = 0; i < 16; i++) { x[i] = (uint8_t)(i*17+3); h[i] = (uint8_t)(i*9+1); }
    ghash_mul_ref(ref, x, h);
    mul_via_bitreverse(o, x, h);
    p("ref", ref); p("bitrev", o);
    printf("match %d\n", memcmp(ref, o, 16)==0);

    /* sanity: bitreverse twice identity */
    __m128i v = _mm_loadu_si128((const __m128i*)x);
    __m128i w = bitreverse128(bitreverse128(v));
    uint8_t wb[16]; _mm_storeu_si128((__m128i*)wb, w);
    p("roundtrip", wb);
    printf("rt %d\n", memcmp(wb, x, 16)==0);
    return 0;
}
