/* The classic "shift reduction" used with byte-swapped inputs.
   From a widely copied implementation (e.g. the one in BearSSL ghash_ctmul.c
   rewritten with pclmul, and from Intel's listing for the reflected field):

   After computing the 256-bit product [hi:lo] of the *byte-swapped* operands
   (so bit 0 of lo is the least significant bit of the reflected polynomial):

   Reduction steps (Gueron, "Intel carry-less multiplication instruction and
   its usage for computing the GCM mode", the reflected variant):

     __m128i T = _mm_srli_epi64? 
   Let me transcribe the exact sequence from the paper's Figure 5 / common code:

     v1 = lo >> 31; v2 = lo >> 30; v3 = lo >> 25;   (64-bit lane shifts)
     lo ^= v1 ^ v2 ^ v3;
     then move the overflow bits (top of each lane) into the next lane and into hi,
     then
     v1 = lo << 1; v2 = lo << 2; v3 = lo << 7;
     hi ^= lo ^ v1 ^ v2 ^ v3;
*/
static __m128i reduce_shift(__m128i lo, __m128i hi) {
    __m128i v1 = _mm_srli_epi64(lo, 31);
    __m128i v2 = _mm_srli_epi64(lo, 30);
    __m128i v3 = _mm_srli_epi64(lo, 25);
