       srli_epi64 drops them. Reconstruct cross-lane carries: */
    /* Actually the standard code does NOT fix cross-lane for the right shift; it uses
       a different arrangement. Let's try the exact published sequence which is:

       tmp7  = lo
       lo    = srli_epi64(lo, 31) ^ srli_epi64(lo, 30) ^ srli_epi64(lo, 25)
       hi    = hi ^ slli_si128(lo, 8)          // move low-lane result into high lane? 
       ... 
       I'll implement several published variants and compare.
    */
    (void)v;
    return hi;
}

/* Variant from https://github.com/Shay-Gueron/AES-GCM-SIV (ghash) and many blogs.
   Exact code commonly seen:

   static inline __m128i gfmul(__m128i a, __m128i b) {
     __m128i tmp0, tmp1, tmp2, tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp9;
     tmp0 = _mm_clmulepi64_si128(a, b, 0x00);
     tmp1 = _mm_clmulepi64_si128(a, b, 0x11);
     tmp2 = _mm_clmulepi64_si128(a, b, 0x10);
     tmp3 = _mm_clmulepi64_si128(a, b, 0x01);
     tmp2 = _mm_xor_si128(tmp2, tmp3);
     tmp3 = _mm_slli_si128(tmp2, 8);
     tmp2 = _mm_srli_si128(tmp2, 8);
     tmp0 = _mm_xor_si128(tmp0, tmp3);
     tmp1 = _mm_xor_si128(tmp1, tmp2);
     // reduction
     tmp3 = _mm_srli_epi64(tmp0, 63);          // note 63 not 31 — different formulation
     ...
   }
*/
static __m128i gfmul_v1(__m128i a, __m128i b) {
    __m128i tmp0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i tmp1 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i tmp2 = _mm_clmulepi64_si128(a, b, 0x10);
    __m128i tmp3 = _mm_clmulepi64_si128(a, b, 0x01);
    tmp2 = _mm_xor_si128(tmp2, tmp3);
    tmp3 = _mm_slli_si128(tmp2, 8);
    tmp2 = _mm_srli_si128(tmp2, 8);
    tmp0 = _mm_xor_si128(tmp0, tmp3); /* lo */
    tmp1 = _mm_xor_si128(tmp1, tmp2); /* hi */
    /* Karatsuba-free reduction from Gueron listing (the 31/30/25 one), carefully
       including cross-lane bits via byte shifts. */
    __m128i t = tmp0;
    __m128i s31 = _mm_srli_epi64(t, 31);
    __m128i s30 = _mm_srli_epi64(t, 30);
    __m128i s25 = _mm_srli_epi64(t, 25);
    t = _mm_xor_si128(_mm_xor_si128(s31, s30), s25);
    /* cross lane: bits that overflowed the low 64 into nowhere must be added to high 64.
       Overflow of a right shift by k of a 64-bit lane is the top k bits, which belong
       at the bottom of the next higher 64. We can get them by left-shifting the lane
       and moving it up 8 bytes. */
    __m128i c31 = _mm_slli_si128(_mm_slli_epi64(tmp0, 33), 8); /* top 31 bits of low lane -> bottom of high lane, shifted right 31 == left 33 then move */
    __m128i c30 = _mm_slli_si128(_mm_slli_epi64(tmp0, 34), 8);
    __m128i c25 = _mm_slli_si128(_mm_slli_epi64(tmp0, 39), 8);
    t = _mm_xor_si128(t, _mm_xor_si128(_mm_xor_si128(c31, c30), c25));
    tmp0 = _mm_xor_si128(tmp0, _mm_slli_si128(t, 8)); /* fold into high half of lo? this is getting speculative */
    tmp1 = _mm_xor_si128(tmp1, _mm_srli_si128(t, 8));
    __m128i l1 = _mm_slli_epi64(tmp0, 1);
    __m128i l2 = _mm_slli_epi64(tmp0, 2);
    __m128i l7 = _mm_slli_epi64(tmp0, 7);
