    __m128i d1 = _mm_srli_si128(_mm_srli_epi64(tmp0, 63), 8);
    __m128i d2 = _mm_srli_si128(_mm_srli_epi64(tmp0, 62), 8);
    __m128i d7 = _mm_srli_si128(_mm_srli_epi64(tmp0, 57), 8);
    __m128i left = _mm_xor_si128(_mm_xor_si128(l1, l2), l7);
    left = _mm_xor_si128(left, _mm_xor_si128(_mm_xor_si128(d1, d2), d7));
    tmp1 = _mm_xor_si128(tmp1, _mm_xor_si128(tmp0, left));
    return tmp1;
}

/* The EXACT sequence from a known-good public file (intel-ipsec-mb / common):
   I will reproduce the version that does reduction purely with clmul by the
   polynomial placed at the TOP of the register (0xe100000000000000), which is
   the other standard formulation. Operand order: reflected, no extra bitreverse.

   From cryptogams ghash-x86_64.pl commentary, the reduction is:
     T1 = pclmulqdq(X0, 0x87?? no)

   Let me try the formulation where we LEFT-shift-reduce using poly constant
   0xe1 << 56 in the high lane, operating on byte-swapped inputs, and the
   result is the low half (not the high half). This is the "other endian" of
   what I tried before.
*/
static __m128i gfmul_v2(__m128i a, __m128i b) {
    __m128i z0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i z1 = _mm_clmulepi64_si128(a, b, 0x10);
    __m128i z2 = _mm_clmulepi64_si128(a, b, 0x01);
    __m128i z3 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i mid = _mm_xor_si128(z1, z2);
    __m128i lo = _mm_xor_si128(z0, _mm_slli_si128(mid, 8));
    __m128i hi = _mm_xor_si128(z3, _mm_srli_si128(mid, 8));
