       Try: multiply hi by 0xe1 and xor into lo, two stages, result = lo. */
    __m128i pe1 = _mm_set_epi64x(0, 0xe1);
    __m128i r0 = _mm_clmulepi64_si128(_mm_move_epi64(hi), pe1, 0x00);
