    __m128i r1 = _mm_clmulepi64_si128(hi_hi, pe1, 0x00);
    /* hi_hi * 0xe1 corresponds to bits 192.. of the original product, which reduce
       to bits 64.. of the result (192-128=64). So shift r1 left by 64 (8 bytes). */
    lo = _mm_xor_si128(lo, _mm_slli_si128(r1, 8));
    return lo;
}

