#include <emmintrin.h>
#include <tmmintrin.h>
#include <smmintrin.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

/* 4-bit table GHASH, SSE2. Tables built once per key.
   This is the classic "ghash 4-bit" approach: 16 x 16-byte products of H by
   0..15, plus a shifted copy, and we process 8 nibbles per byte... actually
   per block we do 32 nibble lookups. With SSE that's a handful of shuffles.
   Expected ~1-2 GB/s/core, fine since AES-CTR dominates and is parallel. */

typedef struct {
    __m128i T[16];     /* H * nibble, memory order, for the low nibble of each byte processed from the right */
    __m128i shift[16]; /* precomputed reduction for the 4 bits shifted out */
} ghash_tab_t;

static void mul_ref(uint8_t out[16], const uint8_t x[16], const uint8_t h[16]) {
    uint8_t z[16] = {0}, v[16]; memcpy(v, h, 16);
    for (int i = 0; i < 16; i++) {
        uint8_t xb = x[i];
        for (int bit = 7; bit >= 0; bit--) {
            if ((xb >> bit) & 1) for (int k = 0; k < 16; k++) z[k] ^= v[k];
            int lsb = v[15] & 1;
            for (int k = 15; k > 0; k--) v[k] = (uint8_t)((v[k] >> 1) | (v[k-1] << 7));
            v[0] = (uint8_t)(v[0] >> 1);
            if (lsb) v[0] ^= 0xe1;
        }
    }
    memcpy(out, z, 16);
}

static void shift_right_4(uint8_t v[16]) {
    /* shift big-endian bitstring right by 4, xor reduction for the low nibble.
       We do it bit by bit 4 times for table building (not hot). */
    for (int s = 0; s < 4; s++) {
        int lsb = v[15] & 1;
        for (int k = 15; k > 0; k--) v[k] = (uint8_t)((v[k] >> 1) | (v[k-1] << 7));
        v[0] = (uint8_t)(v[0] >> 1);
        if (lsb) v[0] ^= 0xe1;
    }
}

static void build(ghash_tab_t *tab, const uint8_t H[16]) {
    uint8_t base[16][16];
    memset(base, 0, sizeof base);
    /* base[n] = H * n, for n = 0..15, where n is the LOW nibble (rightmost 4 bits
       of the 128-bit big-endian integer). */
    for (int n = 1; n < 16; n++) {
        /* add H shifted by the bit position of each set bit in n.
           n's bit 0 is the least significant bit = rightmost bit = already H*1 = H
           shifted right 0 times. n's bit k means H shifted right k times. */
        uint8_t hshift[16]; memcpy(hshift, H, 16);
        for (int k = 0; k < 4; k++) {
            if ((n >> k) & 1) for (int i = 0; i < 16; i++) base[n][i] ^= hshift[i];
            /* shift hshift right 1 */
            int lsb = hshift[15] & 1;
            for (int i = 15; i > 0; i--) hshift[i] = (uint8_t)((hshift[i] >> 1) | (hshift[i-1] << 7));
            hshift[0] = (uint8_t)(hshift[0] >> 1);
            if (lsb) hshift[0] ^= 0xe1;
        }
    }
    for (int n = 0; n < 16; n++) tab->T[n] = _mm_loadu_si128((const __m128i *)base[n]);

    /* reduction table: when we shift the accumulator right by 4, the low nibble
       (v[15] & 0x0f) falls off and must be multiplied by the reduction constant.
       For a right shift of 4 on a big-endian bit string, the fallen nibble's
       contribution to the TOP of the register is rem[n] where n = fallen nibble.
       Easier: precompute for each possible fallen nibble the 16-byte value to xor
       after a plain 4-bit right shift. We'll just compute it by reference. */
    for (int n = 0; n < 16; n++) {
        uint8_t v[16] = {0};
        v[15] = (uint8_t)n; /* only low nibble set */
        uint8_t before[16]; memcpy(before, v, 16);
        shift_right_4(v);
        /* plain shift without reduction: */
        uint8_t plain[16] = {0};
        plain[15] = (uint8_t)(n >> 4); /* 0 */
        /* The difference between reduced shift and plain shift is the reduction term. */
        uint8_t red[16];
        for (int i = 0; i < 16; i++) red[i] = v[i] ^ plain[i];
        tab->shift[n] = _mm_loadu_si128((const __m128i *)red);
        (void)before;
    }
}

static inline __m128i shift_right_4_sse(__m128i v, const ghash_tab_t *tab) {
    int n = _mm_extract_epi8(v, 15) & 0x0f;
    /* plain right shift by 4 bits across the 16 bytes */
    __m128i lo = _mm_srli_epi64(v, 4);
    __m128i hi_bits = _mm_slli_epi64(v, 60);          /* top 4 bits of each 64-bit lane */
    hi_bits = _mm_srli_si128(hi_bits, 8);             /* move low lane's overflow into high lane */
    /* also the top 4 bits of the high lane fall off (handled by reduction table),
       and the low lane needs the top 4 bits of... wait, within the 128-bit big-endian
       byte string, a right shift by 4 moves each byte's low nibble to the high nibble
       of the next byte. srli_epi64 does that within each 64-bit lane but the boundary
       between byte 7 and byte 8 (the two lanes) needs the low lane's top 4 bits to
       enter the high lane's bottom. That's what hi_bits does. The top 4 bits of the
       high lane (byte 0's top nibble) fall off the left? NO.

       Careful: our register is in memory order, byte 0 is the most significant byte
       (leftmost). _mm_srli_epi64 shifts toward the LOW end of each lane, which is
       toward higher byte indices within a lane? Let's think in bytes.

       Memory byte 0 is the most significant. In an XMM register, byte 0 is the LEAST
       significant byte of the low lane (lane bits 0..7). So a big-endian right shift
       (toward the last byte) is a shift toward HIGHER byte indices = toward the high
       lane = a LEFT shift in the native integer sense! I had the direction backwards.

       Big-endian bit-string right shift by 4 = each byte's low nibble moves to the
       high nibble of the NEXT byte (byte i+1), and byte 15's low nibble falls off.
       In register terms (byte 0 at the low address / low lane low byte), that is a
       shift of the whole 128-bit register toward higher bytes, i.e. _mm_slli_si128
       by 0 plus nibble fixups. Let's just do it byte-wise with a shuffle to be safe
       and clear. */
    (void)lo; (void)hi_bits; (void)n;
    uint8_t b[16], o[16];
    _mm_storeu_si128((__m128i *)b, v);
    int fallen = b[15] & 0x0f;
    for (int i = 15; i > 0; i--) o[i] = (uint8_t)((b[i] >> 4) | (b[i-1] << 4));
    o[0] = (uint8_t)(b[0] >> 4);
    __m128i r = _mm_loadu_si128((const __m128i *)o);
    r = _mm_xor_si128(r, tab->shift[fallen]);
    return r;
}

static __m128i ghash_block(__m128i acc, __m128i block, const ghash_tab_t *tab) {
    acc = _mm_xor_si128(acc, block);
    __m128i z = _mm_setzero_si128();
    /* process nibbles from most significant (byte 0 high nibble) to least */
    uint8_t b[16];
    _mm_storeu_si128((__m128i *)b, acc);
    for (int i = 0; i < 16; i++) {
        int hi = b[i] >> 4;
        int lo = b[i] & 0x0f;
        /* z = z * x^4 xor H*hi, then z = z * x^4 xor H*lo */
        z = shift_right_4_sse(z, tab);
        z = _mm_xor_si128(z, tab->T[hi]);
        z = shift_right_4_sse(z, tab);
        z = _mm_xor_si128(z, tab->T[lo]);
    }
    return z;
}

static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return ts.tv_sec + ts.tv_nsec*1e-9; }

int main() {
    uint8_t H[16], x[16], ref[16];
    for (int i = 0; i < 16; i++) { H[i] = (uint8_t)(i*9+1); x[i] = (uint8_t)(i*17+3); }
    ghash_tab_t tab; build(&tab, H);
    mul_ref(ref, x, H);
    __m128i r = ghash_block(_mm_setzero_si128(), _mm_loadu_si128((const __m128i*)x), &tab);
    uint8_t o[16]; _mm_storeu_si128((__m128i*)o, r);
    printf("ref "); for (int i=0;i<16;i++) printf("%02x", ref[i]); printf("\n");
    printf("out "); for (int i=0;i<16;i++) printf("%02x", o[i]); printf(" match %d\n", memcmp(o,ref,16)==0);

    int ok = 1;
    for (int t = 0; t < 30; t++) {
        for (int i = 0; i < 16; i++) { x[i] = (uint8_t)(i*t*3+t*5+1); H[i] = (uint8_t)(i*t*7+t*9+2); }
        build(&tab, H);
        mul_ref(ref, x, H);
        r = ghash_block(_mm_setzero_si128(), _mm_loadu_si128((const __m128i*)x), &tab);
        _mm_storeu_si128((__m128i*)o, r);
        if (memcmp(o, ref, 16)) { ok = 0; printf("fail %d\n", t); break; }
    }
    printf("all ok %d\n", ok);

    /* speed */
    size_t N = 60000L*1024;
    uint8_t *buf = malloc(N);
    memset(buf, 1, N);
    for (int i = 0; i < 16; i++) H[i] = (uint8_t)(i+1);
    build(&tab, H);
    __m128i acc = _mm_setzero_si128();
    double t0 = now();
    int reps = 1;
    for (int rep = 0; rep < reps; rep++) {
        acc = _mm_setzero_si128();
        for (size_t i = 0; i < N; i += 16) {
            acc = ghash_block(acc, _mm_loadu_si128((const __m128i*)(buf+i)), &tab);
        }
    }
    double t1 = now();
    printf("ghash %.3f s  %.0f MB/s\n", (t1-t0)/reps, (N/1e6)/((t1-t0)/reps));
    _mm_storeu_si128((__m128i*)o, acc);
    printf("acc "); for (int i=0;i<16;i++) printf("%02x", o[i]); printf("\n");
    return 0;
}
