    _mm_storeu_si128((__m128i*)lob, _mm_shuffle_epi8(lo, mask));
    _mm_storeu_si128((__m128i*)hib, _mm_shuffle_epi8(hi, mask));
    p("cswap lo", lob, 16);
    p("cswap hi", hib, 16);
    return 0;
}
