#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <stdlib.h>

static inline void mul128(uint64_t x0, uint64_t x1, uint64_t y0, uint64_t y1,
                          uint64_t *r0, uint64_t *r1, uint64_t *r2, uint64_t *r3) {
    /* 128x128 -> 256, little-endian word order: x0 is low 64 bits (x^0..x^63). */
    /* use __uint128_t */
    unsigned __int128 z00 = (unsigned __int128)x0 * 0; /* placeholder to keep compiler happy? no, we need carryless. */
    (void)z00; (void)y0; (void)y1; (void)r0; (void)r1; (void)r2; (void)r3; (void)x1;
}

/* carryless multiply 64x64 -> 128 via 4 32x32 using integer mul and masking? 
   Faster: 8x8 table? Let's just write a 64x64 clmul using a loop of 4-bit with
   shift, or use the compiler intrinsic which we KNOW works, and do reduction in
   integer code where I can see it. */
#include <wmmintrin.h>

static inline void clmul64(uint64_t a, uint64_t b, uint64_t *hi, uint64_t *lo) {
    __m128i p = _mm_clmulepi64_si128(_mm_set_epi64x(0, (long long)a), _mm_set_epi64x(0, (long long)b), 0x00);
    *lo = (uint64_t)_mm_cvtsi128_si64(p);
    *hi = (uint64_t)_mm_extract_epi64(p, 1);
}

/* GHASH multiply. X and H are big-endian 16-byte blocks. */
static void ghash_mul(uint8_t x[16], const uint8_t h[16]) {
    /* Convert to a polynomial where bit 0 of a 128-bit little-endian integer is x^0
       = the LEAST significant bit of the big-endian integer = byte 15 bit 0.
       So the 128-bit LE integer is just the big-endian byte string interpreted as a
       big-endian integer. Low 64 bits = bytes 8..15 interpreted big-endian. */
    uint64_t x_hi = 0, x_lo = 0, h_hi = 0, h_lo = 0;
    for (int i = 0; i < 8; i++) { x_hi = (x_hi << 8) | x[i]; h_hi = (h_hi << 8) | h[i]; }
    for (int i = 8; i < 16; i++) { x_lo = (x_lo << 8) | x[i]; h_lo = (h_lo << 8) | h[i]; }
    /* Now x_lo bit 0 = x^0, x_hi bit 63 = x^127. Good, this is the mathematical integer. */
    uint64_t z0_lo, z0_hi, z1_lo, z1_hi, z2_lo, z2_hi, z3_lo, z3_hi;
    clmul64(x_lo, h_lo, &z0_hi, &z0_lo); /* bits 0..127 */
    clmul64(x_lo, h_hi, &z1_hi, &z1_lo); /* bits 64..191 */
    clmul64(x_hi, h_lo, &z2_hi, &z2_lo); /* bits 64..191 */
    clmul64(x_hi, h_hi, &z3_hi, &z3_lo); /* bits 128..255 */
    /* assemble 256-bit product p0 (bits 0-63) p1 (64-127) p2 (128-191) p3 (192-255) */
    uint64_t p0 = z0_lo;
    uint64_t p1 = z0_hi ^ z1_lo ^ z2_lo;
    uint64_t p2 = z3_lo ^ z1_hi ^ z2_hi;
    uint64_t p3 = z3_hi;

    /* Reduce mod x^128 + x^7 + x^2 + x + 1. poly = 0x87.
       p0 and p1 are bits 0..127, fold them into bits 128.. by multiplying by 0x87. */
    uint64_t r0_lo, r0_hi, r1_lo, r1_hi;
    clmul64(p0, 0x87, &r0_hi, &r0_lo); /* bits 0..63 * poly -> positions 128..198 => p2 gets r0_lo, p3 gets r0_hi (only low bits) */
    clmul64(p1, 0x87, &r1_hi, &r1_lo); /* bits 64..127 * poly -> positions 192..262 */
    p2 ^= r0_lo;
    p3 ^= r0_hi;
    p3 ^= r1_lo;
    /* r1_hi is bits 256..262+ (at most bit 262). x^256 ≡ poly^2? 
       position 256+t = x^{256+t} = x^{128+t} * x^{128} ≡ x^{128+t} * poly.
       r1_hi bit t represents x^{256+t}, which should become poly << (128+t), i.e. xor 0x87<<t into bits 128.. 
       So xor (r1_hi * 0x87) into p2/p3. r1_hi is at most 7 bits, cheap. */
    uint64_t ov_lo, ov_hi;
    clmul64(r1_hi, 0x87, &ov_hi, &ov_lo);
    p2 ^= ov_lo;
    p3 ^= ov_hi;
    /* result is bits 128..255 = p2 (low) and p3 (high) */
    for (int i = 7; i >= 0; i--) { x[i] = (uint8_t)(p3 & 0xff); p3 >>= 8; }
    for (int i = 15; i >= 8; i--) { x[i] = (uint8_t)(p2 & 0xff); p2 >>= 8; }
}

static void ghash_mul_ref(uint8_t out[16], const uint8_t xin[16], const uint8_t h[16]) {
    uint8_t z[16] = {0}, v[16]; memcpy(v, h, 16);
    for (int i = 0; i < 16; i++) {
        uint8_t xb = xin[i];
        for (int bit = 7; bit >= 0; bit--) {
            if ((xb >> bit) & 1) for (int k = 0; k < 16; k++) z[k] ^= v[k];
            int lsb = v[15] & 1;
            for (int k = 15; k > 0; k--) v[k] = (uint8_t)((v[k] >> 1) | (v[k-1] << 7));
            v[0] = (uint8_t)(v[0] >> 1);
            if (lsb) v[0] ^= 0xe1;
        }
    }
    memcpy(out, z, 16);
}

static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return ts.tv_sec + ts.tv_nsec*1e-9; }

int main() {
    uint8_t x[16], h[16], ref[16], o[16];
    int ok = 1;
    for (int t = 0; t < 50; t++) {
        for (int i = 0; i < 16; i++) { x[i] = (uint8_t)(i*t*3 + t*17 + 5); h[i] = (uint8_t)(i*t*9 + t*13 + 1); }
