    memset(buf, 1, N);
    for (int i = 0; i < 16; i++) h[i] = (uint8_t)(i+1);
    uint8_t acc[16] = {0};
    double t0 = now();
    for (size_t i = 0; i < N; i += 16) {
        for (int k = 0; k < 16; k++) acc[k] ^= buf[i+k];
        ghash_mul(acc, h);
    }
    double t1 = now();
    printf("ghash64 %.3f s  %.0f MB/s\n", t1-t0, (N/1e6)/(t1-t0));
    return 0;
}
