#include <wmmintrin.h>
#include <emmintrin.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>

static inline void clmul64(uint64_t a, uint64_t b, uint64_t *hi, uint64_t *lo) {
    __m128i p = _mm_clmulepi64_si128(_mm_set_epi64x(0, (long long)a), _mm_set_epi64x(0, (long long)b), 0x00);
    *lo = (uint64_t)_mm_cvtsi128_si64(p);
    *hi = (uint64_t)_mm_cvtsi128_si64(_mm_srli_si128(p, 8));
}

/* x = x * h in GHASH. Reflected convention: byte 0 bit 0 of the memory block is x^0
   after we bit-reverse each byte and treat the block as a little-endian integer?
   We instead bit-reverse the whole block into a LE integer (byte 0 bit 7 -> bit 0),
   multiply with poly x^128+x^7+x^2+x+1 = 0x87, and bit-reverse back. */
static inline uint64_t brev64(uint64_t x) {
    x = ((x & 0x5555555555555555ULL) << 1) | ((x >> 1) & 0x5555555555555555ULL);
    x = ((x & 0x3333333333333333ULL) << 2) | ((x >> 2) & 0x3333333333333333ULL);
    x = ((x & 0x0f0f0f0f0f0f0f0fULL) << 4) | ((x >> 4) & 0x0f0f0f0f0f0f0f0fULL);
    x = ((x & 0x00ff00ff00ff00ffULL) << 8) | ((x >> 8) & 0x00ff00ff00ff00ffULL);
    x = ((x & 0x0000ffff0000ffffULL) << 16) | ((x >> 16) & 0x0000ffff0000ffffULL);
    return (x << 32) | (x >> 32);
}

static void ghash_mul(uint8_t x[16], const uint8_t h[16]) {
    /* Load block as big-endian integer, then bit-reverse so that the MSB of the
       big-endian integer (byte0 bit7 = x^127 in NIST, which is the first bit
       tested) becomes bit 0. NIST iterates from the top bit and right-shifts V,
       which is exactly multiplication in the reflected field. */
    uint64_t x_hi=0,x_lo=0,h_hi=0,h_lo=0;
    for (int i=0;i<8;i++){ x_hi=(x_hi<<8)|x[i]; h_hi=(h_hi<<8)|h[i]; }
    for (int i=8;i<16;i++){ x_lo=(x_lo<<8)|x[i]; h_lo=(h_lo<<8)|h[i]; }
    /* bit-reverse the 128-bit value: new low 64 = bitreverse(old high 64) */
    uint64_t xr_lo = brev64(x_hi), xr_hi = brev64(x_lo);
    uint64_t hr_lo = brev64(h_hi), hr_hi = brev64(h_lo);
    uint64_t z0_lo,z0_hi,z1_lo,z1_hi,z2_lo,z2_hi,z3_lo,z3_hi;
    clmul64(xr_lo, hr_lo, &z0_hi, &z0_lo);
    clmul64(xr_lo, hr_hi, &z1_hi, &z1_lo);
    clmul64(xr_hi, hr_lo, &z2_hi, &z2_lo);
    clmul64(xr_hi, hr_hi, &z3_hi, &z3_lo);
    uint64_t p0 = z0_lo;
    uint64_t p1 = z0_hi ^ z1_lo ^ z2_lo;
    uint64_t p2 = z3_lo ^ z1_hi ^ z2_hi;
    uint64_t p3 = z3_hi;
    /* reduce p2,p3 (bits >= 128) into p0,p1 with poly 0x87 */
    uint64_t r2_lo,r2_hi,r3_lo,r3_hi,ov_lo,ov_hi;
    clmul64(p2, 0x87, &r2_hi, &r2_lo);
    clmul64(p3, 0x87, &r3_hi, &r3_lo);
    p0 ^= r2_lo; p1 ^= r2_hi; p1 ^= r3_lo;
    clmul64(r3_hi, 0x87, &ov_hi, &ov_lo);
    p0 ^= ov_lo; p1 ^= ov_hi;
    /* bit-reverse back: p0 is low 64 of reflected result = bitreverse of high 64 of output */
    uint64_t out_hi = brev64(p0);
    uint64_t out_lo = brev64(p1);
    for (int i=7;i>=0;i--){ x[i]=(uint8_t)(out_hi & 0xff); out_hi >>= 8; }
    for (int i=15;i>=8;i--){ x[i]=(uint8_t)(out_lo & 0xff); out_lo >>= 8; }
}

static void ghash_mul_ref(uint8_t out[16], const uint8_t xin[16], const uint8_t h[16]) {
    uint8_t z[16]={0}, v[16]; memcpy(v, h, 16);
    for (int i=0;i<16;i++){
        uint8_t xb=xin[i];
        for (int bit=7; bit>=0; bit--){
            if ((xb>>bit)&1) for (int k=0;k<16;k++) z[k]^=v[k];
            int lsb=v[15]&1;
            for (int k=15;k>0;k--) v[k]=(uint8_t)((v[k]>>1)|(v[k-1]<<7));
            v[0]=(uint8_t)(v[0]>>1);
            if (lsb) v[0]^=0xe1;
        }
    }
    memcpy(out, z, 16);
}

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

int main(){
    uint8_t x[16], h[16], ref[16], o[16];
    int ok=1;
    for (int t=0;t<200;t++){
        for (int i=0;i<16;i++){ x[i]=(uint8_t)(i*t*3+t*17+5); h[i]=(uint8_t)(i*t*9+t*13+1); }
        ghash_mul_ref(ref, x, h);
        memcpy(o, x, 16); ghash_mul(o, h);
        if (memcmp(o, ref, 16)){ ok=0; printf("fail t=%d\n", t);
            printf("ref "); for(int i=0;i<16;i++) printf("%02x", ref[i]);
            printf("\nout "); for(int i=0;i<16;i++) printf("%02x", o[i]); printf("\n");
            break; }
    }
    printf("ok %d\n", ok);
    if (!ok) return 1;
    size_t N=60000L*1024; uint8_t *buf=malloc(N); memset(buf,1,N);
    for(int i=0;i<16;i++) h[i]=(uint8_t)(i+1);
    uint8_t acc[16]={0};
    double t0=now();
    for (size_t i=0;i<N;i+=16){ for(int k=0;k<16;k++) acc[k]^=buf[i+k]; ghash_mul(acc,h); }
    double t1=now();
    printf("ghash64 %.3f s  %.0f MB/s\n", t1-t0, (N/1e6)/(t1-t0));
    return 0;
}
