static inline void load_be128(const uint8_t *p, uint64_t *hi, uint64_t *lo) {
    uint64_t h=0, l=0;
    for (int i=0;i<8;i++) h = (h<<8) | p[i];
    for (int i=8;i<16;i++) l = (l<<8) | p[i];
