static inline void store_be128(uint8_t *p, uint64_t hi, uint64_t lo) {
    for (int i=7;i>=0;i--) { p[i] = (uint8_t)hi; hi >>= 8; }
    for (int i=15;i>=8;i--) { p[i] = (uint8_t)lo; lo >>= 8; }
