static inline void ghash_block(uint64_t *acc_lo, uint64_t *acc_hi, const uint8_t blk[16], uint64_t hr_lo, uint64_t hr_hi) {
    uint64_t b_hi, b_lo; load_be128(blk, &b_hi, &b_lo);
    *acc_lo ^= brev64(b_hi);
    *acc_hi ^= brev64(b_lo);
    mul_reflected(acc_lo, acc_hi, hr_lo, hr_hi);
