/* AES-128 key schedule + 8-wide CTR */
typedef struct { __m128i rk[11]; } aes128_t;
static inline __m128i expand(__m128i k, __m128i a) {
    k = _mm_xor_si128(k, _mm_slli_si128(k, 4));
    k = _mm_xor_si128(k, _mm_slli_si128(k, 4));
    k = _mm_xor_si128(k, _mm_slli_si128(k, 4));
    return _mm_xor_si128(k, _mm_shuffle_epi32(a, 0xff));
}
static void aes128_key(aes128_t *ks, const uint8_t key[16]) {
    __m128i k = _mm_loadu_si128((const __m128i*)key);
    ks->rk[0]=k;
    #define E(i,r) do { k = expand(k, _mm_aeskeygenassist_si128(k, r)); ks->rk[i]=k; } while(0)
    E(1,0x01); E(2,0x02); E(3,0x04); E(4,0x08); E(5,0x10);
    E(6,0x20); E(7,0x40); E(8,0x80); E(9,0x1b); E(10,0x36);
    #undef E
}
static inline __m128i aes_block(const aes128_t *ks, __m128i b) {
    b = _mm_xor_si128(b, ks->rk[0]);
    b = _mm_aesenc_si128(b, ks->rk[1]); b = _mm_aesenc_si128(b, ks->rk[2]);
    b = _mm_aesenc_si128(b, ks->rk[3]); b = _mm_aesenc_si128(b, ks->rk[4]);
    b = _mm_aesenc_si128(b, ks->rk[5]); b = _mm_aesenc_si128(b, ks->rk[6]);
    b = _mm_aesenc_si128(b, ks->rk[7]); b = _mm_aesenc_si128(b, ks->rk[8]);
    b = _mm_aesenc_si128(b, ks->rk[9]);
    return _mm_aesenclast_si128(b, ks->rk[10]);
}
static void ctr_xor(const aes128_t *ks, const uint8_t nonce[12], uint32_t counter,
                    const uint8_t *in, uint8_t *out, size_t len) {
    uint8_t cb[16]; memcpy(cb, nonce, 12);
    size_t blocks = len/16, i = 0;
    while (i + 8 <= blocks) {
        __m128i c[8];
        for (int k=0;k<8;k++) {
            uint32_t ctr = counter + (uint32_t)(i+k);
            cb[12]=(ctr>>24)&0xff; cb[13]=(ctr>>16)&0xff; cb[14]=(ctr>>8)&0xff; cb[15]=ctr&0xff;
            c[k] = _mm_xor_si128(_mm_loadu_si128((const __m128i*)cb), ks->rk[0]);
        }
        for (int r=1;r<10;r++) for (int k=0;k<8;k++) c[k] = _mm_aesenc_si128(c[k], ks->rk[r]);
        for (int k=0;k<8;k++) {
            c[k] = _mm_aesenclast_si128(c[k], ks->rk[10]);
            __m128i p = _mm_loadu_si128((const __m128i*)(in + (i+k)*16));
            _mm_storeu_si128((__m128i*)(out + (i+k)*16), _mm_xor_si128(c[k], p));
        }
        i += 8;
    }
    while (i < blocks) {
        uint32_t ctr = counter + (uint32_t)i;
        cb[12]=(ctr>>24)&0xff; cb[13]=(ctr>>16)&0xff; cb[14]=(ctr>>8)&0xff; cb[15]=ctr&0xff;
        __m128i c = aes_block(ks, _mm_loadu_si128((const __m128i*)cb));
        __m128i p = _mm_loadu_si128((const __m128i*)(in + i*16));
        _mm_storeu_si128((__m128i*)(out + i*16), _mm_xor_si128(c, p));
        i++;
    }
    size_t rem = len - blocks*16;
    if (rem) {
        uint32_t ctr = counter + (uint32_t)blocks;
        cb[12]=(ctr>>24)&0xff; cb[13]=(ctr>>16)&0xff; cb[14]=(ctr>>8)&0xff; cb[15]=ctr&0xff;
        __m128i c = aes_block(ks, _mm_loadu_si128((const __m128i*)cb));
        uint8_t ks_stream[16]; _mm_storeu_si128((__m128i*)ks_stream, c);
        for (size_t j=0;j<rem;j++) out[blocks*16+j] = in[blocks*16+j] ^ ks_stream[j];
    }
