typedef struct {
    const aes128_t *ks;
    const uint8_t *nonce;
    const uint8_t *pt;
    uint8_t *ct;
    size_t off, len;
    uint64_t hr_lo, hr_hi;
    uint64_t acc_lo, acc_hi;
    uint64_t blocks;
} job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    uint32_t counter = 2u + (uint32_t)(j->off/16);
    ctr_xor(j->ks, j->nonce, counter, j->pt + j->off, j->ct + j->off, j->len);
    uint64_t acc_lo=0, acc_hi=0;
    size_t full = j->len & ~15UL;
    const uint8_t *c = j->ct + j->off;
    for (size_t i=0;i<full;i+=16) ghash_block(&acc_lo, &acc_hi, c+i, j->hr_lo, j->hr_hi);
    j->acc_lo = acc_lo; j->acc_hi = acc_hi; j->blocks = full/16;
    return NULL;
}

static void h_pow(uint64_t hr_lo, uint64_t hr_hi, uint64_t n, uint64_t *out_lo, uint64_t *out_hi) {
    /* identity in reflected representation: the integer 1, NIST memory 00..01,
       bit-reversed: byte0 bit7 set -> reflected low bit 0 set? 
       NIST byte15=0x01 is x^0. Our reflected accumulator has bit 0 = NIST's first
       bit (byte0 bit7 = x^127). So the multiplicative identity (x^0) is NIST
       byte15 bit0, which after full bit-reverse of the 128-bit big-endian integer
       lands at bit 0. brev64(0) for high, brev64(1) for low -> reflected hi = brev64(1),
       reflected lo = 0. Identity: xr_lo=0, xr_hi=brev64(1). */
    uint64_t r_lo = 0, r_hi = brev64(1);
    uint64_t b_lo = hr_lo, b_hi = hr_hi;
    while (n) {
        if (n & 1) mul_reflected(&r_lo, &r_hi, b_lo, b_hi);
        uint64_t s_lo=b_lo, s_hi=b_hi;
        mul_reflected(&s_lo, &s_hi, b_lo, b_hi);
        b_lo=s_lo; b_hi=s_hi;
        n >>= 1;
    }
    *out_lo = r_lo; *out_hi = r_hi;
}

int aesgcm_encrypt(const uint8_t key[16], const uint8_t nonce[12],
                   const uint8_t *pt, int pt_len, const uint8_t *aad, int aad_len,
                   uint8_t *ct, uint8_t tag[16], int nthreads) {
    aes128_t ks; aes128_key(&ks, key);
    __m128i h_block = aes_block(&ks, _mm_setzero_si128());
    uint8_t H[16]; _mm_storeu_si128((__m128i*)H, h_block);
    uint64_t h_hi, h_lo; load_be128(H, &h_hi, &h_lo);
    uint64_t hr_lo = brev64(h_hi), hr_hi = brev64(h_lo);

    size_t N = (size_t)pt_len;
    if (nthreads < 1) nthreads = 1;
    if (nthreads > MAX_THREADS) nthreads = MAX_THREADS;

    uint64_t acc_lo=0, acc_hi=0;
    /* AAD */
    if (aad && aad_len > 0) {
        size_t full = (size_t)aad_len & ~15UL;
        for (size_t i=0;i<full;i+=16) ghash_block(&acc_lo, &acc_hi, aad+i, hr_lo, hr_hi);
        size_t rem = (size_t)aad_len - full;
        if (rem) { uint8_t last[16]={0}; memcpy(last, aad+full, rem); ghash_block(&acc_lo, &acc_hi, last, hr_lo, hr_hi); }
    }

    if (nthreads > 1 && N >= (1<<20)) {
        size_t full = N & ~15UL;
        size_t chunk = (full / nthreads) & ~15UL;
        if (chunk) {
            pthread_t th[MAX_THREADS]; job_t jobs[MAX_THREADS]; int live=0;
            for (int i=0;i<nthreads;i++) {
                size_t off = (size_t)i * chunk;
                if (off >= full) break;
                jobs[i].ks=&ks; jobs[i].nonce=nonce; jobs[i].pt=pt; jobs[i].ct=ct;
                jobs[i].off=off; jobs[i].len = (i==nthreads-1) ? (N-off) : chunk;
                jobs[i].hr_lo=hr_lo; jobs[i].hr_hi=hr_hi;
                pthread_create(&th[i], NULL, worker, &jobs[i]);
                live++;
            }
            for (int i=0;i<live;i++) pthread_join(th[i], NULL);
            for (int i=0;i<live;i++) {
                if (jobs[i].blocks) {
                    uint64_t p_lo, p_hi; h_pow(hr_lo, hr_hi, jobs[i].blocks, &p_lo, &p_hi);
                    mul_reflected(&acc_lo, &acc_hi, p_lo, p_hi);
                    acc_lo ^= jobs[i].acc_lo; acc_hi ^= jobs[i].acc_hi;
                }
            }
            size_t rem = N & 15UL;
            if (rem) { uint8_t last[16]={0}; memcpy(last, ct+N-rem, rem); ghash_block(&acc_lo, &acc_hi, last, hr_lo, hr_hi); }
            goto finish;
        }
    }
    ctr_xor(&ks, nonce, 2, pt, ct, N);
    {
        size_t full = N & ~15UL;
        for (size_t i=0;i<full;i+=16) ghash_block(&acc_lo, &acc_hi, ct+i, hr_lo, hr_hi);
        size_t rem = N & 15UL;
        if (rem) { uint8_t last[16]={0}; memcpy(last, ct+full, rem); ghash_block(&acc_lo, &acc_hi, last, hr_lo, hr_hi); }
    }
finish:;
    uint8_t lenb[16]={0};
    uint64_t aad_bits = (uint64_t)(aad_len>0?aad_len:0) * 8;
    uint64_t pt_bits = (uint64_t)pt_len * 8;
    for (int i=7;i>=0;i--){ lenb[i]=(uint8_t)aad_bits; aad_bits>>=8; }
    for (int i=15;i>=8;i--){ lenb[i]=(uint8_t)pt_bits; pt_bits>>=8; }
    ghash_block(&acc_lo, &acc_hi, lenb, hr_lo, hr_hi);
    /* tag = AES(counter 1) xor byteswap-back of accumulator */
    uint8_t cb[16]; memcpy(cb, nonce, 12); cb[12]=0; cb[13]=0; cb[14]=0; cb[15]=1;
    __m128i s = aes_block(&ks, _mm_loadu_si128((const __m128i*)cb));
    uint8_t sb[16]; _mm_storeu_si128((__m128i*)sb, s);
    uint8_t g[16];
    uint64_t out_hi = brev64(acc_lo), out_lo = brev64(acc_hi);
    store_be128(g, out_hi, out_lo);
    for (int i=0;i<16;i++) tag[i] = sb[i] ^ g[i];
    return 0;
}

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

int main() {
    uint8_t key[16], nonce[12], aad[32];
    for (int i=0;i<16;i++) key[i]=i+1;
    for (int i=0;i<12;i++) nonce[i]=i;
