    printf("empty tag "); for (int i=0;i<16;i++) printf("%02x", tag[i]); printf("\n");

    size_t N = 60000L*1024;
    uint8_t *PT = malloc(N), *CT = malloc(N);
    memset(PT, 0x11, N);
    for (int nt=1; nt<=8; nt*=2) {
        aesgcm_encrypt(key, nonce, PT, (int)N, aad, 32, CT, tag, nt);
        double t0=now(); int reps=2;
        for (int r=0;r<reps;r++) aesgcm_encrypt(key, nonce, PT, (int)N, aad, 32, CT, tag, nt);
