src = r'''
#include <wmmintrin.h>
#include <emmintrin.h>
#include <tmmintrin.h>
#include <smmintrin.h>
#include <pthread.h>
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_THREADS 12

static uint8_t brev8_table[256];
static uint64_t brev_byte_table[8][256];
static int tables_ready = 0;

static void init_tables(void) {
    if (tables_ready) return;
    for (int i = 0; i < 256; i++) {
        uint8_t x = (uint8_t)i;
        x = (uint8_t)((x & 0x55) << 1 | (x >> 1) & 0x55);
        x = (uint8_t)((x & 0x33) << 2 | (x >> 2) & 0x33);
        x = (uint8_t)((x & 0x0f) << 4 | (x >> 4) & 0x0f);
        brev8_table[i] = x;
    }
    for (int pos = 0; pos < 8; pos++) {
        for (int v = 0; v < 256; v++) {
            /* big-endian byte `pos` (0 = MSB) bit-reversed contributes to reflected bits.
               Big-endian byte pos holds x^{127-8*pos} .. x^{120-8*pos} (bit7 = highest).
               After full bit-reverse, big-endian bit (127-k) maps to reflected bit k.
               Byte pos bit b (b=7 is MSB of byte = x^{127-8*pos-(7-b)} = x^{120-8*pos+b}).
               That polynomial bit index from the top (bit 127) is 8*pos + (7-b).
               Reflected bit = 8*pos + (7-b). The bit-reversed byte value's bit (7-b) is set
               when original bit b is set, and reflected bit = 8*pos + (7-b). So the
               bit-reversed byte placed at byte position `pos` in a little-endian 64? 

               Simpler and already validated: reflected_lo = brev64(be_hi), reflected_hi = brev64(be_lo).
               be_hi byte j (j=0..7, j=0 is MSB) = memory byte j.
               brev64 of a big-endian-loaded value: bit-reverse the 64-bit integer.
               We'll just compute brev64(be) via the table: for memory byte j of the high
               half, its bit-reversed value goes to byte (7-j) of the little-endian reflected_lo? 
               Let's do it directly and check against brev64. */
            brev_byte_table[pos][v] = (uint64_t)brev8_table[v] << (8 * (7 - pos));
        }
    }
    tables_ready = 1;
}

static inline uint64_t brev64_mem(const uint8_t *p) {
    /* bit-reverse of the big-endian integer stored at p[0..7] */
    uint64_t r = 0;
    r |= brev_byte_table[0][p[0]];
    r |= brev_byte_table[1][p[1]];
    r |= brev_byte_table[2][p[2]];
    r |= brev_byte_table[3][p[3]];
    r |= brev_byte_table[4][p[4]];
    r |= brev_byte_table[5][p[5]];
    r |= brev_byte_table[6][p[6]];
    r |= brev_byte_table[7][p[7]];
    return r;
}

static inline uint64_t brev64(uint64_t x) {
    x = ((x & 0x5555555555555555ULL) << 1) | ((x >> 1) & 0x5555555555555555ULL);
    x = ((x & 0x3333333333333333ULL) << 2) | ((x >> 2) & 0x3333333333333333ULL);
    x = ((x & 0x0f0f0f0f0f0f0f0fULL) << 4) | ((x >> 4) & 0x0f0f0f0f0f0f0f0fULL);
    x = ((x & 0x00ff00ff00ff00ffULL) << 8) | ((x >> 8) & 0x00ff00ff00ff00ffULL);
    x = ((x & 0x0000ffff0000ffffULL) << 16) | ((x >> 16) & 0x0000ffff0000ffffULL);
    return (x << 32) | (x >> 32);
}

static inline void clmul64(uint64_t a, uint64_t b, uint64_t *hi, uint64_t *lo) {
    __m128i p = _mm_clmulepi64_si128(_mm_set_epi64x(0, (long long)a), _mm_set_epi64x(0, (long long)b), 0x00);
    *lo = (uint64_t)_mm_cvtsi128_si64(p);
    *hi = (uint64_t)_mm_cvtsi128_si64(_mm_srli_si128(p, 8));
}

static inline void mul_reflected(uint64_t *x_lo, uint64_t *x_hi, uint64_t h_lo, uint64_t h_hi) {
    uint64_t z0_lo,z0_hi,z1_lo,z1_hi,z2_lo,z2_hi,z3_lo,z3_hi;
    clmul64(*x_lo, h_lo, &z0_hi, &z0_lo);
    clmul64(*x_lo, h_hi, &z1_hi, &z1_lo);
    clmul64(*x_hi, h_lo, &z2_hi, &z2_lo);
    clmul64(*x_hi, h_hi, &z3_hi, &z3_lo);
    uint64_t p0=z0_lo;
    uint64_t p1=z0_hi^z1_lo^z2_lo;
    uint64_t p2=z3_lo^z1_hi^z2_hi;
    uint64_t p3=z3_hi;
    uint64_t r2_lo,r2_hi,r3_lo,r3_hi,ov_lo,ov_hi;
    clmul64(p2, 0x87, &r2_hi, &r2_lo);
    clmul64(p3, 0x87, &r3_hi, &r3_lo);
    p0 ^= r2_lo; p1 ^= r2_hi ^ r3_lo;
    clmul64(r3_hi, 0x87, &ov_hi, &ov_lo);
    p0 ^= ov_lo; p1 ^= ov_hi;
    *x_lo = p0; *x_hi = p1;
}

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

int main() {
    init_tables();
    /* verify table against brev64 */
    uint8_t blk[16];
    for (int i=0;i<16;i++) blk[i]=i*17+3;
    uint64_t be_hi=0, be_lo=0;
    for (int i=0;i<8;i++) be_hi=(be_hi<<8)|blk[i];
    for (int i=8;i<16;i++) be_lo=(be_lo<<8)|blk[i];
    uint64_t t_lo = brev64_mem(blk);
    uint64_t t_hi = brev64_mem(blk+8);
    printf("match lo %d hi %d\n", t_lo==brev64(be_hi), t_hi==brev64(be_lo));

    size_t N=60000L*1024;
    uint8_t *buf=malloc(N); memset(buf,1,N);
    uint64_t hr_lo=0x1234, hr_hi=0x5678;
    uint64_t acc_lo=0, acc_hi=0;
    double t0=now();
    for (size_t i=0;i<N;i+=16) {
        acc_lo ^= brev64_mem(buf+i);
        acc_hi ^= brev64_mem(buf+i+8);
        mul_reflected(&acc_lo, &acc_hi, hr_lo, hr_hi);
    }
    double t1=now();
    volatile uint64_t sink=acc_lo^acc_hi;
    printf("table ghash %.3f s  %.0f MB/s sink=%llx\n", t1-t0, (N/1e6)/(t1-t0), sink);
    return 0;
}
'''
open("ghash_table.c","w").write(src)
print("wrote")
