/* Persistent worker pool. Threads are created once and reused, so the benchmark's
   timed solve() does not pay thread-creation cost. */
static pthread_t pool_threads[MAX_THREADS];
static job_t *pool_jobs[MAX_THREADS];
static int pool_size = 0;
static int pool_stop = 0;
static pthread_mutex_t pool_mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t pool_cv = PTHREAD_COND_INITIALIZER;       /* workers wait for work */
static pthread_cond_t pool_done_cv = PTHREAD_COND_INITIALIZER;  /* main waits for completion */
static int pool_epoch = 0;       /* bumped to dispatch a new round */
static int pool_remaining = 0;   /* workers still running this round */

static void *pool_worker(void *arg) {
    int id = (int)(intptr_t)arg;
    int seen = 0;
    for (;;) {
        pthread_mutex_lock(&pool_mu);
        while (pool_epoch == seen && !pool_stop) pthread_cond_wait(&pool_cv, &pool_mu);
        if (pool_stop) { pthread_mutex_unlock(&pool_mu); break; }
        seen = pool_epoch;
        job_t *job = pool_jobs[id];
        pthread_mutex_unlock(&pool_mu);
        if (job) worker(job);
        pthread_mutex_lock(&pool_mu);
        pool_remaining--;
        if (pool_remaining == 0) pthread_cond_signal(&pool_done_cv);
        pthread_mutex_unlock(&pool_mu);
    }
    return NULL;
}

static void pool_ensure(int n) {
    if (pool_size >= n) return;
    for (int i = pool_size; i < n; i++) {
        pthread_create(&pool_threads[i], NULL, pool_worker, (void*)(intptr_t)i);
    }
    pool_size = n;
}

static void pool_run(job_t *jobs, int n) {
    pool_ensure(n);
    pthread_mutex_lock(&pool_mu);
    for (int i = 0; i < n; i++) pool_jobs[i] = &jobs[i];
    for (int i = n; i < pool_size; i++) pool_jobs[i] = NULL;
    pool_remaining = n;
    pool_epoch++;
    pthread_cond_broadcast(&pool_cv);
    while (pool_remaining > 0) pthread_cond_wait(&pool_done_cv, &pool_mu);
    pthread_mutex_unlock(&pool_mu);
}
