#include <wmmintrin.h>
#include <emmintrin.h>
#include <tmmintrin.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>

static inline uint64_t brev64(uint64_t x) {
    x = ((x & 0x5555555555555555ULL) << 1) | ((x >> 1) & 0x5555555555555555ULL);
    x = ((x & 0x3333333333333333ULL) << 2) | ((x >> 2) & 0x3333333333333333ULL);
    x = ((x & 0x0f0f0f0f0f0f0f0fULL) << 4) | ((x >> 4) & 0x0f0f0f0f0f0f0f0fULL);
    x = ((x & 0x00ff00ff00ff00ffULL) << 8) | ((x >> 8) & 0x00ff00ff00ff00ffULL);
    x = ((x & 0x0000ffff0000ffffULL) << 16) | ((x >> 16) & 0x0000ffff0000ffffULL);
    return (x << 32) | (x >> 32);
}
static inline void clmul64(uint64_t a, uint64_t b, uint64_t *hi, uint64_t *lo) {
    __m128i p = _mm_clmulepi64_si128(_mm_set_epi64x(0,(long long)a), _mm_set_epi64x(0,(long long)b), 0x00);
    *lo = (uint64_t)_mm_cvtsi128_si64(p);
    *hi = (uint64_t)_mm_cvtsi128_si64(_mm_srli_si128(p, 8));
}
static inline void mul_reflected(uint64_t *x_lo, uint64_t *x_hi, uint64_t h_lo, uint64_t h_hi) {
    uint64_t z0_lo,z0_hi,z1_lo,z1_hi,z2_lo,z2_hi,z3_lo,z3_hi;
    clmul64(*x_lo, h_lo, &z0_hi, &z0_lo);
    clmul64(*x_lo, h_hi, &z1_hi, &z1_lo);
    clmul64(*x_hi, h_lo, &z2_hi, &z2_lo);
    clmul64(*x_hi, h_hi, &z3_hi, &z3_lo);
    uint64_t p0=z0_lo, p1=z0_hi^z1_lo^z2_lo, p2=z3_lo^z1_hi^z2_hi, p3=z3_hi;
    uint64_t r2_lo,r2_hi,r3_lo,r3_hi,ov_lo,ov_hi;
    clmul64(p2, 0x87, &r2_hi, &r2_lo);
    clmul64(p3, 0x87, &r3_hi, &r3_lo);
    p0 ^= r2_lo; p1 ^= r2_hi ^ r3_lo;
    clmul64(r3_hi, 0x87, &ov_hi, &ov_lo);
    p0 ^= ov_lo; p1 ^= ov_hi;
    *x_lo=p0; *x_hi=p1;
}

/* 4-block aggregated GHASH: compute X0*H^4 xor X1*H^3 xor X2*H^2 xor X3*H with one
   reduction each, using precomputed powers. Still 4 multiplies but the reductions
   can be partially shared? For a first cut, just do 4 independent muls and xor,
   which has the same mul count. The win is only from reduction aggregation.
   Let's instead time a version that precomputes H^2, H^3, H^4 and does the
   schoolbook sum — same 4 muls. Skip; time pclmul throughput bound instead. */

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

int main() {
    size_t N = 60000L*1024;
    uint8_t *buf = malloc(N); memset(buf, 1, N);
    /* pre-bitreverse all blocks so we measure pure multiply throughput */
    uint64_t *lo = malloc(sizeof(uint64_t) * (N/16));
    uint64_t *hi = malloc(sizeof(uint64_t) * (N/16));
    for (size_t i=0;i<N;i+=16) {
        uint64_t a,b; memcpy(&a, buf+i, 8); memcpy(&b, buf+i+8, 8);
        lo[i/16] = brev64(__builtin_bswap64(a));
        hi[i/16] = brev64(__builtin_bswap64(b));
    }
    uint64_t hr_lo = 0x123456789abcdef0ULL, hr_hi = 0x0fedcba987654321ULL;
    uint64_t acc_lo=0, acc_hi=0;
    size_t blocks = N/16;
    double t0 = now();
    for (size_t i=0;i<blocks;i++) {
        acc_lo ^= lo[i]; acc_hi ^= hi[i];
        mul_reflected(&acc_lo, &acc_hi, hr_lo, hr_hi);
    }
    double t1 = now();
    volatile uint64_t sink = acc_lo^acc_hi;
    printf("pure mul %.3f s %.0f MB/s sink=%llx\n", t1-t0, (N/1e6)/(t1-t0), sink);

    /* 2-way: two independent accumulators (would be wrong for GHASH but measures ILP) */
    uint64_t a0l=0,a0h=0,a1l=0,a1h=0;
    t0 = now();
    for (size_t i=0;i+1<blocks;i+=2) {
        a0l ^= lo[i]; a0h ^= hi[i]; mul_reflected(&a0l, &a0h, hr_lo, hr_hi);
        a1l ^= lo[i+1]; a1h ^= hi[i+1]; mul_reflected(&a1l, &a1h, hr_lo, hr_hi);
    }
    t1 = now();
    sink = a0l^a1l^a0h^a1h;
    printf("2-way indep %.3f s %.0f MB/s sink=%llx\n", t1-t0, (N/1e6)/(t1-t0), sink);
    return 0;
}
