#include <wmmintrin.h>
#include <emmintrin.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>

static inline uint64_t brev64(uint64_t x) {
    x = ((x & 0x5555555555555555ULL) << 1) | ((x >> 1) & 0x5555555555555555ULL);
    x = ((x & 0x3333333333333333ULL) << 2) | ((x >> 2) & 0x3333333333333333ULL);
    x = ((x & 0x0f0f0f0f0f0f0f0fULL) << 4) | ((x >> 4) & 0x0f0f0f0f0f0f0f0fULL);
    x = ((x & 0x00ff00ff00ff00ffULL) << 8) | ((x >> 8) & 0x00ff00ff00ff00ffULL);
    x = ((x & 0x0000ffff0000ffffULL) << 16) | ((x >> 16) & 0x0000ffff0000ffffULL);
    return (x << 32) | (x >> 32);
}
static inline void clmul64(uint64_t a, uint64_t b, uint64_t *hi, uint64_t *lo) {
    __m128i p = _mm_clmulepi64_si128(_mm_set_epi64x(0,(long long)a), _mm_set_epi64x(0,(long long)b), 0x00);
    *lo = (uint64_t)_mm_cvtsi128_si64(p);
    *hi = (uint64_t)_mm_cvtsi128_si64(_mm_srli_si128(p, 8));
}

/* 4-way aggregated: acc = (((acc ^ X0) * H^4) ^ (X1*H^3) ^ (X2*H^2) ^ (X3*H))
   but computed as xor of 4 products then ONE reduction. Products:
     (acc^X0)*H4, X1*H3, X2*H2, X3*H1
   Each product is a 128x128 -> 256, we xor the 256-bit products, reduce once. */
typedef struct { uint64_t lo, hi; } u128;
static u128 Hpow[5];

static inline void mul_full(uint64_t x_lo, uint64_t x_hi, uint64_t h_lo, uint64_t h_hi,
                            uint64_t *p0, uint64_t *p1, uint64_t *p2, uint64_t *p3) {
    uint64_t z0_lo,z0_hi,z1_lo,z1_hi,z2_lo,z2_hi,z3_lo,z3_hi;
    clmul64(x_lo, h_lo, &z0_hi, &z0_lo);
    clmul64(x_lo, h_hi, &z1_hi, &z1_lo);
    clmul64(x_hi, h_lo, &z2_hi, &z2_lo);
    clmul64(x_hi, h_hi, &z3_hi, &z3_lo);
    *p0 = z0_lo;
    *p1 = z0_hi ^ z1_lo ^ z2_lo;
    *p2 = z3_lo ^ z1_hi ^ z2_hi;
    *p3 = z3_hi;
}
static inline void reduce(uint64_t p0, uint64_t p1, uint64_t p2, uint64_t p3, uint64_t *o_lo, uint64_t *o_hi) {
    uint64_t r2_lo,r2_hi,r3_lo,r3_hi,ov_lo,ov_hi;
    clmul64(p2, 0x87, &r2_hi, &r2_lo);
    clmul64(p3, 0x87, &r3_hi, &r3_lo);
    p0 ^= r2_lo; p1 ^= r2_hi ^ r3_lo;
    clmul64(r3_hi, 0x87, &ov_hi, &ov_lo);
    *o_lo = p0 ^ ov_lo; *o_hi = p1 ^ ov_hi;
}
static inline void mul_one(uint64_t *x_lo, uint64_t *x_hi, u128 h) {
    uint64_t p0,p1,p2,p3;
    mul_full(*x_lo, *x_hi, h.lo, h.hi, &p0, &p1, &p2, &p3);
    reduce(p0, p1, p2, p3, x_lo, x_hi);
}

static void ghash4(uint64_t *acc_lo, uint64_t *acc_hi, const uint64_t *lo, const uint64_t *hi) {
    uint64_t a0 = *acc_lo ^ lo[0], b0 = *acc_hi ^ hi[0];
    uint64_t p0=0,p1=0,p2=0,p3=0;
    uint64_t q0,q1,q2,q3;
    mul_full(a0, b0, Hpow[4].lo, Hpow[4].hi, &q0, &q1, &q2, &q3);
    p0^=q0; p1^=q1; p2^=q2; p3^=q3;
    mul_full(lo[1], hi[1], Hpow[3].lo, Hpow[3].hi, &q0, &q1, &q2, &q3);
    p0^=q0; p1^=q1; p2^=q2; p3^=q3;
    mul_full(lo[2], hi[2], Hpow[2].lo, Hpow[2].hi, &q0, &q1, &q2, &q3);
    p0^=q0; p1^=q1; p2^=q2; p3^=q3;
    mul_full(lo[3], hi[3], Hpow[1].lo, Hpow[1].hi, &q0, &q1, &q2, &q3);
    p0^=q0; p1^=q1; p2^=q2; p3^=q3;
    reduce(p0, p1, p2, p3, acc_lo, acc_hi);
}

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

int main() {
    /* build powers: H^1 = H, H^2 = H*H, ... */
    Hpow[1].lo = 0x123456789abcdef0ULL; Hpow[1].hi = 0x0fedcba987654321ULL;
    Hpow[2] = Hpow[1]; mul_one(&Hpow[2].lo, &Hpow[2].hi, Hpow[1]);
    Hpow[3] = Hpow[2]; mul_one(&Hpow[3].lo, &Hpow[3].hi, Hpow[1]);
    Hpow[4] = Hpow[3]; mul_one(&Hpow[4].lo, &Hpow[4].hi, Hpow[1]);

    size_t N = 60000L*1024;
    size_t blocks = N/16;
    uint64_t *lo = calloc(blocks, 8), *hi = calloc(blocks, 8);
    for (size_t i=0;i<blocks;i++) { lo[i]=i*3+1; hi[i]=i*7+9; }

    /* reference serial */
    uint64_t r_lo=0, r_hi=0;
    for (size_t i=0;i<blocks;i++) { r_lo^=lo[i]; r_hi^=hi[i]; mul_one(&r_lo, &r_hi, Hpow[1]); }

    uint64_t a_lo=0, a_hi=0;
    double t0=now();
    int reps=3;
    for (int rep=0; rep<reps; rep++) {
        a_lo=0; a_hi=0;
        size_t i=0;
        for (; i+4<=blocks; i+=4) ghash4(&a_lo, &a_hi, lo+i, hi+i);
        for (; i<blocks; i++) { a_lo^=lo[i]; a_hi^=hi[i]; mul_one(&a_lo, &a_hi, Hpow[1]); }
    }
    double t1=now();
    printf("4-agg %.4f s %.0f MB/s match %d\n", (t1-t0)/reps, (N/1e6)/((t1-t0)/reps), a_lo==r_lo && a_hi==r_hi);
    if (!(a_lo==r_lo && a_hi==r_hi)) printf(" got %llx %llx ref %llx %llx\n", a_hi, a_lo, r_hi, r_lo);
    return 0;
