/* 256-bit product of two reflected 128-bit values. */
static inline void mul_full(uint64_t x_lo, uint64_t x_hi, uint64_t h_lo, uint64_t h_hi,
                            uint64_t *p0, uint64_t *p1, uint64_t *p2, uint64_t *p3) {
    uint64_t z0_lo,z0_hi,z1_lo,z1_hi,z2_lo,z2_hi,z3_lo,z3_hi;
    clmul64(x_lo, h_lo, &z0_hi, &z0_lo);
    clmul64(x_lo, h_hi, &z1_hi, &z1_lo);
    clmul64(x_hi, h_lo, &z2_hi, &z2_lo);
    clmul64(x_hi, h_hi, &z3_hi, &z3_lo);
    *p0 = z0_lo;
    *p1 = z0_hi ^ z1_lo ^ z2_lo;
    *p2 = z3_lo ^ z1_hi ^ z2_hi;
