/* Hash 4 reflected blocks: acc = (((acc ^ X0) * H^4) ^ X1*H^3 ^ X2*H^2 ^ X3*H) */
static inline void ghash4_reflected(uint64_t *acc_lo, uint64_t *acc_hi,
                                    uint64_t x0_lo, uint64_t x0_hi,
                                    uint64_t x1_lo, uint64_t x1_hi,
                                    uint64_t x2_lo, uint64_t x2_hi,
                                    uint64_t x3_lo, uint64_t x3_hi,
                                    const uint64_t *hp_lo, const uint64_t *hp_hi) {
