    mul_full(x2_lo, x2_hi, hp_lo[2], hp_hi[2], &q0,&q1,&q2,&q3);
    p0^=q0; p1^=q1; p2^=q2; p3^=q3;
    mul_full(x3_lo, x3_hi, hp_lo[1], hp_hi[1], &q0,&q1,&q2,&q3);
    p0^=q0; p1^=q1; p2^=q2; p3^=q3;
