static void ghash_range(uint64_t *acc_lo, uint64_t *acc_hi, const uint8_t *data, size_t len,
                        uint64_t hr_lo, uint64_t hr_hi,
                        const uint64_t *hp_lo, const uint64_t *hp_hi) {
    size_t blocks = len / 16;
    size_t i = 0;
    while (i + 4 <= blocks) {
        uint64_t x_lo[4], x_hi[4];
        reflect_block(data + (i+0)*16, &x_lo[0], &x_hi[0]);
        reflect_block(data + (i+1)*16, &x_lo[1], &x_hi[1]);
        reflect_block(data + (i+2)*16, &x_lo[2], &x_hi[2]);
        reflect_block(data + (i+3)*16, &x_lo[3], &x_hi[3]);
